import { accounts } from '@acme/module-accounts';
import { defineModuleBase, type ModuleBaseType } from '@keelwerk/core';
import { toAccounts } from './contributions/to-accounts/contribution.ts';
import { order } from './entities/order.ts';

const shopBaseDef = defineModuleBase({
  id: 'shop',
  version: '0.1.0',
  optional: [accounts],
  entities: { order },
  contributions: { toAccounts },
});

export interface ShopBase extends ModuleBaseType<typeof shopBaseDef> {}
export const shopBase: ShopBase = shopBaseDef;

import { defineEntity, type EntityType, field } from '@keelwerk/core';

const orderDef = defineEntity({ prefix: 'ord', fields: { total: field.integer() } });

export interface Order extends EntityType<typeof orderDef> {}
export const order: Order = orderDef;

